      "cover-wrap|disqus|extra|footer|gdpr|header|legends|menu|related|" +
      "remark|replies|rss|shoutbox|sidebar|skyscraper|social|sponsor|" +
      "shopping|shopper|retailer|supplemental|(?:\\b|_)ad-break|agegate|" +
